{
 "job": "lost_stolen_card_cross_product_security_protocol",
 "when": {
  "quote": "When a customer reports a lost or stolen debit card, there is a risk that other cards in their wallet were also compromised.",
  "doc": "doc_bank_accounts_bank_accounts_(general)_030"
 },
 "info": [
  {
   "field": "credit_card_in_wallet",
   "about": "whether the customer's Rho-Bank credit card was also in the lost or stolen wallet",
   "from": "customer",
   "ask": "I see you also have a credit card with us. Was that card also in your lost wallet?",
   "may_hold_back": true
  }
 ],
 "steps": [
  {
   "id": "check_cc",
   "by": "harness",
   "do": "Check whether the customer has any Rho-Bank credit cards",
   "call": "get_credit_card_accounts_by_user",
   "args": {
    "user_id": "the verified user"
   },
   "after": [],
   "if": null,
   "quote": "Use get_credit_card_accounts_by_user to retrieve any credit card accounts for the customer.",
   "doc": "doc_bank_accounts_bank_accounts_(general)_030"
  },
  {
   "id": "offer_cc",
   "by": "model",
   "do": "Ask whether the credit card was also in the wallet, and offer a replacement with a new number",
   "call": null,
   "args": {},
   "after": [
    "check_cc"
   ],
   "if": "the customer has an active credit card",
   "quote": "Offer to order a replacement credit card with a new card number to prevent any unauthorized charges",
   "doc": "doc_bank_accounts_bank_accounts_(general)_030"
  },
  {
   "id": "unlock_cc_order",
   "by": "harness",
   "do": "Unlock the credit card replacement tool",
   "call": "unlock_discoverable_agent_tool",
   "args": {
    "agent_tool_name": "order_replacement_credit_card_7291"
   },
   "after": [
    "offer_cc"
   ],
   "if": "the customer accepts the replacement",
   "quote": "Use unlock_discoverable_agent_tool with tool_name: order_replacement_credit_card_7291.",
   "doc": "doc_credit_cards_credit_card_replacements_001"
  },
  {
   "id": "order_cc",
   "by": "harness",
   "do": "Order the replacement credit card. Strongly recommend expedited shipping when the card was stolen.",
   "call": "call_discoverable_agent_tool",
   "args": {
    "agent_tool_name": "order_replacement_credit_card_7291",
    "account": "the credit card account id",
    "reason": "stolen or lost",
    "shipping_address": "the confirmed address",
    "shipping_speed": "standard or expedited"
   },
   "after": [
    "unlock_cc_order"
   ],
   "if": "the customer accepts the replacement",
   "quote": "If the reason is fraud_suspected or stolen, strongly recommend expedited shipping to minimize exposure and remind the customer to review recent transactions for unauthorized activity.",
   "doc": "doc_credit_cards_credit_card_replacements_001"
  }
 ],
 "rules": [
  {
   "rule": "After handling a lost or stolen debit card, always check for credit cards and offer a replacement if any exist",
   "quote": "If yes, proactively offer to order a replacement credit card as a security precaution",
   "doc": "doc_bank_accounts_bank_accounts_(general)_030"
  }
 ],
 "done_when": "The credit card check is done. If the customer has a credit card, the replacement offer has been made and acted on or declined."
}
